const STEP_TYPES = new Set(["command_execution", "mcp_tool_call", "file_change"]);

function agentCommand(run, harness, prompt) {
  const mcpEnv = {
    BENANA_INTENT_DIR: run.intentDir,
    BENANA_ATTEMPT: String(run.attempt),
    BENANA_RUN_ID: run.id,
  };
  if (run.kind === "codex") {
    const config = [
